class Solution {
    public int minDeletionSize(String[] strs){
        int deleted=0;
        for(int col=0;col<strs[0].length();col++){
            for(int row=1;row<strs.length;row++)if(strs[row-1].charAt(col)>strs[row].charAt(col)){
                deleted++;
                break;
            }
        }
        return deleted;
    }
}

code.kotlin:
class Solution {
    fun minDeletionSize(strs:Array<String>):Int{
        var deleted=0;
        for(col in strs[0].indices){
            for(row in 1 until strs.size)if(strs[row-1][col]>strs[row][col]){
                deleted++;
                break
            }
        };
        return deleted
    }
}

